import sys, json
raw = sys.stdin.read().strip()
# Find the start of the JSON object
idx = raw.find('{')
if idx >= 0:
    raw = raw[idx:]
# Find the last }
end = raw.rfind('}')
if end >= 0:
    raw = raw[:end+1]
data = json.loads(raw)
json.dump(data, open('after-cpm-packages.json', 'w'), indent=2)
print('Wrote after-cpm-packages.json')
print(f'Projects: {len(data[\"projects\"])}')
for p in data['projects']:
    name = p['path'].split('/')[-1]
    for fw in p['frameworks']:
        pkgs = [pkg['id'] + '=' + pkg['resolvedVersion'] for pkg in fw['topLevelPackages']]
        print(f'  {name} ({fw[\"framework\"]}): {\" | \".join(pkgs)}')
"
